function [cadfilename1,caddisease,datatype,dist1,numstartpoints,B,model,params,vars,getperformance,forecastingperiod,windowsize1,tstart1,tend1,printscreen1] = options_main_JAL_GRM
% Generated by 01_prepare_inputs.R - edit the R config, not this file.
% Analysis: main | Jalisco | GRM model
% Calibration: onset weeks 2025-09-08 to 2026-06-08 (40 weeks); forecast horizon 8 weeks

global method1

cadfilename1 = 'JAL_main';
caddisease   = 'measles';
datatype     = 'cases';

method1 = 3;   % MLE negative binomial, VAR = mean + alpha*mean (NB1)
dist1   = 3;

numstartpoints = 100;
B              = 300;

model.fc   = @GRM;
model.name = 'GRM model';

params.num     = 4;
params.label   = {'r','p','a','K'};
params.LB      = [0.001 0.01 0.01 7476];
params.UB      = [20 1 10 74760];
params.initial = [0.5 0.8 1 8971.2];
params.fixed   = [0 0 0 0];
params.fixI0   = 1;   % C(0) fixed to the first observation
params.composite      = [];
params.composite_name = '';
params.extra0         = [];

vars.num       = 1;
vars.label     = {'C'};
vars.initial   = 1;   % overridden because params.fixI0 = 1
vars.fit_index = 1;
vars.fit_diff  = 1;   % fit incidence (derivative of C)

getperformance    = 1;
forecastingperiod = 8;
windowsize1       = 40;
tstart1           = 1;
tend1             = 1;
printscreen1      = 0;   % figures are made by 05_figures.R
end
